<?php require 'config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){$error='Use a name, valid email, and password of at least 8 characters.';}else{$hash=password_hash($password,PASSWORD_DEFAULT);try{$stmt=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$stmt->bind_param('sss',$name,$email,$hash);$stmt->execute();redirect('login.php');}catch(mysqli_sql_exception $exception){$error=$exception->getCode()===1062?'That email is already registered.':'Unable to create the account.';}}}page_start('Create account'); ?><section class="section-space"><div class="container"><div class="row justify-content-center"><div class="col-md-6 col-lg-4"><div class="eyebrow">Join the hub</div><h1 class="display-6 mb-4">Create account.</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="form-outline mb-3"><input class="form-control" name="name" required><label class="form-label">Full name</label></div><div class="form-outline mb-3"><input class="form-control" type="email" name="email" required><label class="form-label">Email address</label></div><div class="form-outline mb-4"><input class="form-control" type="password" name="password" minlength="8" required><label class="form-label">Password</label></div><button class="btn btn-dark btn-rounded w-100">Create account</button></form></div></div></div></section><?php page_end(); ?>